guidance.correct_example:
import ast

def parse_config(a_value: str) -> Result[dict]:
    try:
        parsed = ast.literal_eval(a_value)
    except (ValueError, SyntaxError) as e:
        return Result.failure(f'Invalid config: {e}')
    if not isinstance(parsed, dict):
        return Result.failure('Expected dict')
    return Result.success(parsed)

